mapper.select:
select
 COUNT(*) as fillingTotal,
 COUNT(DISTINCT tf.P_Id) as projectTotal,
 COUNT(DISTINCT pro.p_Construction_Unit) as cpyTotal
 from
 t_information_filling  tf
 LEFT join pre_project pro on pro.p_id=tf.P_Id
 left join sys_company cpy on cpy.c_id=pro.p_Construction_Unit
 where pro.p_Construction_Unit is not null
 
     and INSTR(cpy.c_name,#{params.pConstructionUnitName})
 
 
     and cpy.c_type=#{params.pConstructionUnitType}
 
 
     and tf.reporting_Year=#{params.yearFilter}
 
 
     and tf.reporting_Month=#{params.monthFilter}
 
 
     and pro.province=#{params.province}
 
 
     and pro.city=#{params.city}
 
 
     and pro.P_Each_District=#{params.pEachDistrict}

select
DISTINCT
cpy.c_name as pConstructionUnitName,
cpy.c_type as pConstructionUnitType
from
t_information_filling  tf
LEFT join pre_project pro on pro.p_id=tf.P_Id
left join sys_company cpy on cpy.c_id=pro.p_Construction_Unit
where pro.p_Construction_Unit is not null

    and INSTR(cpy.c_name,#{params.pConstructionUnitName})


    and cpy.c_type=#{params.pConstructionUnitType}


    and tf.reporting_Year=#{params.yearFilter}


    and tf.reporting_Month=#{params.monthFilter}


    and pro.province=#{params.province}


    and pro.city=#{params.city}


    and pro.P_Each_District=#{params.pEachDistrict}

WITH project_stat AS ( SELECT pp.p_Construction_Unit, COUNT(CASE WHEN pp.State=7 THEN 1 END) AS projectAddNew -- 仅统计State=7的项目 FROM pre_project pp WHERE 1=1
AND pp.province=#{params.province}
AND pp.city=#{params.city}
AND pp.P_Each_District=#{params.pEachDistrict}
AND TO_CHAR(pp.P_Create_Time,'yyyy-MM')=CONCAT(#{params.yearFilter},'-',#{params.monthFilter})
GROUP BY pp.p_Construction_Unit ), filling_stat AS ( SELECT pp.p_Construction_Unit, COUNT(DISTINCT tif.p_id) AS projectCount, COUNT(*) AS fillingCount, COUNT(CASE WHEN tif.reporting_Year=#{params.lastYear} AND tif.reporting_Month=#{params.lastMonth} THEN 1 END) AS lastFillingCount FROM t_information_filling tif LEFT JOIN pre_project pp ON pp.p_id=tif.P_Id WHERE 1=1
AND pp.province=#{params.province}
AND pp.city=#{params.city}
AND pp.P_Each_District=#{params.pEachDistrict}
GROUP BY pp.p_Construction_Unit ), base_data AS ( SELECT DISTINCT p.p_Construction_Unit, c.c_name, c.c_type FROM t_information_filling tf LEFT JOIN pre_project p ON p.p_id=tf.P_Id LEFT JOIN sys_company c ON c.c_id=p.p_Construction_Unit WHERE p.p_Construction_Unit IS NOT NULL
AND c.c_type=#{params.pConstructionUnitType}
AND tf.reporting_Year=#{params.yearFilter}
AND tf.reporting_Month=#{params.monthFilter}
AND p.province=#{params.province}
AND p.city=#{params.city}
AND p.P_Each_District=#{params.pEachDistrict}
AND c.c_name LIKE CONCAT('%',#{params.pConstructionUnitName},'%')
) SELECT bd.p_Construction_Unit AS pConstructionUnit, bd.c_name AS pConstructionUnitName, bd.c_type AS pConstructionUnitType, NVL(ps.projectAddNew, 0) AS projectAddNew, NVL(fs.projectCount, 0) AS projectCount, NVL(fs.fillingCount, 0) AS fillingCount, NVL(fs.lastFillingCount, 0) AS lastFillingCount FROM base_data bd LEFT JOIN project_stat ps ON bd.p_Construction_Unit = ps.p_Construction_Unit LEFT JOIN filling_stat fs ON bd.p_Construction_Unit = fs.p_Construction_Unit ORDER BY bd.p_Construction_Unit OFFSET #{start} ROWS FETCH NEXT #{limit} ROWS ONLY;

select
    DISTINCT
    pro.p_Construction_Unit as pConstructionUnit,
    cpy.c_name as pConstructionUnitName,
    cpy.c_type as pConstructionUnitType,
    (select Count(*) from pre_project pp where pp.p_Construction_Unit=pro.p_Construction_Unit and pp.State=7
        
            and pp.province=#{params.province}
        
        
            and pp.city=#{params.city}
        
        
            and pp.P_Each_District=#{params.pEachDistrict}
        
        
            and  TO_CHAR(pp.P_Create_Time,'yyyy-MM')=CONCAT(#{params.yearFilter},'-',#{params.monthFt})
        
    ) as projectAddNew,
    (select  count(DISTINCT tif.p_id) from t_information_filling tif left join pre_project pp
        on pp.p_id=tif.P_Id where pp.p_Construction_Unit=pro.p_Construction_Unit
        
            and tif.reporting_Year=#{params.yearFilter}
        
        
            and tif.reporting_Month=#{params.monthFilter}
        
        
            and pp.province=#{params.province}
        
        
            and pp.city=#{params.city}
        
        
            and pp.P_Each_District=#{params.pEachDistrict}
        
    ) as projectCount,
    (select count(*) from t_information_filling tif left join pre_project pp
    on pp.p_id=tif.P_Id where pp.p_Construction_Unit=pro.p_Construction_Unit
    
        and tif.reporting_Year=#{params.yearFilter}
    
    
        and tif.reporting_Month=#{params.monthFilter}
    
    
        and pp.province=#{params.province}
    
    
        and pp.city=#{params.city}
    
    
        and pp.P_Each_District=#{params.pEachDistrict}
    
    ) as fillingCount,
    (select count(*) from t_information_filling tif left join pre_project pp
    on pp.p_id=tif.P_Id where pp.p_Construction_Unit=pro.p_Construction_Unit
    
        and tif.reporting_Year=#{params.lastYear}
    
    
        and tif.reporting_Month=#{params.lastMonth}
    
    
        and pp.province=#{params.province}
    
    
        and pp.city=#{params.city}
    
    
        and pp.P_Each_District=#{params.pEachDistrict}
    
    ) as lastFillingCount
from
    t_information_filling  tf
        LEFT join pre_project pro on pro.p_id=tf.P_Id
        left join sys_company cpy on cpy.c_id=pro.p_Construction_Unit
where pro.p_Construction_Unit is not null

    and cpy.c_type=#{params.pConstructionUnitType}


    and tf.reporting_Year=#{params.yearFilter}


    and tf.reporting_Month=#{params.monthFilter}


    and pro.province=#{params.province}


    and pro.city=#{params.city}


    and pro.P_Each_District=#{params.pEachDistrict}


    and INSTR(cpy.c_name,#{params.pConstructionUnitName})

limit #{start},#{limit}

select mn.p_name,mn.P_Longitude,mn.P_Latitude, mn.p_type as pType, mn.p_Professional_Type as pProfessionalType, mn.p_Build_Model as pBuildModel, mn.p_Construction_Area, mn.p_Building_Unit as pBuildingUnit, mn.p_Total_Duration, mn.p_Scale_Describe, mn.p_Calculate_Roughly_Amount, mn.p_Estimate_Amount, mn.p_Approve_Budget, mn.p_Plan_Start_Date, mn.p_Actual_Start_Time, mn.p_Plan_Complete_Date, (case WHEN mn.p_Bim=1 then 'V' else 'X' end) as pBim, (case WHEN mn.p_Smart_Site=1 then 'V' else 'X' end) as pSmartSite, (case WHEN mn.p_Management_System=1 then 'V' else 'X' end) as pManagementSystem, (case WHEN mn.p_New_Technology=1 then 'V' else 'X' end) as pNewTechnology, (case WHEN mn.p_New_Material=1 then 'V' else 'X' end) as pNewMaterial, (case WHEN mn.p_New_Craft=1 then 'V' else 'X' end) as pNewCraft, (case WHEN mn.p_Save_Energy=1 then 'V' else 'X' end) as pSaveEnergy, (case WHEN mn.p_Save_Land=1 then 'V' else 'X' end) as pSaveLand, (case WHEN mn.p_Save_Water=1 then 'V' else 'X' end) as pSaveWater, (case WHEN mn.p_Save_Material=1 then 'V' else 'X' end) as pSaveMaterial, (case WHEN mn.p_Is_Prefabricated=1 then 'V' else 'X' end) as pIsPrefabricated, (case WHEN mn.p_Digital_Construction=1 then 'V' else 'X' end) as pDigitalConstruction, mn.p_Green_Construction as pGreenConstruction, (case WHEN mn.p_Centralized_Construction=1 then 'V' else 'X' end) as pCentralizedConstruction, mn.p_Contracting_Mode as pContractingMode, (case WHEN mn.p_Process_Consulting=1 then 'V' else 'X' end) as pProcessConsulting, (case WHEN mn.p_Engineer_Responsible=1 then 'V' else 'X' end) as pEngineerResponsible from pre_project mn ${params.authSql}
and mn.p_type=#{params.pType}
and mn.p_Professional_Type=#{params.pProfessionalType}
and mn.state=#{params.state}
and INSTR(mn.p_name,#{params.pName})
and INSTR(mn.P_Create_User_Name,#{params.pCreateUserName})
and mn.p_create_time>=#{params.pCreateTimeStart}
and mn.p_create_time <=#{params.pCreateTimeEnd}
